entries[1224767] = { ["name"] = "Knecht des Königs", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin Spielercharakter erliegt seinem Schwur und wird 12 Sek. lang gedankenkontrolliert. Die Leere kräftigt den Spielercharakter und heilt ihn vollständig.\n\nWenn der Effekt ausläuft, explodieren die Untergebenen und fügen dabei allen Spielercharakteren 100 Schattenschaden zu." }
entries[1224775] = { ["name"] = "Halskette der Ergebenen", ["text"] = "Ihr gehört zu den Ergebenen. Steigert die Effektivität von 'Schutz der Heiligen Flamme' um 100%.\n\nSchutz der Heiligen Flamme :\nWährend Ihr Euch in Khaz Algar befindet, besteht beim Verursachen von Schaden eine hohe Chance, den Gegner mit rechtschaffenem Feuer zu verbrennen und ihm so 2 Strahlenschaden zuzufügen. Außerdem erleidet Ihr 5% weniger Schaden." }
