entries[1225069] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRamponierte Aegis\nWährend die Aegis ausgerüstet ist, verursachen alle Gruppenmitglieder 3 % mehr Schaden und Heilung. Im Kampf heilt Ihr und Brann alle 10 Sek. um 5 % des Schadens, den Ihr in dieser Zeit erlitten habt.\n\nStirbt ein Spielercharakter, gewährt die Aegis diesem bei der Wiederbelebung 1 % Schadensverringerung und 2 % erhöhte Heilung, reduziert jedoch seinen verursachten Schaden und die Heilung um 1 %. Dieser Effekt ist bis zu 3-mal stapelbar.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[1225070] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRamponierte Aegis\nWährend die Aegis ausgerüstet ist, verursachen alle Gruppenmitglieder 6 % mehr Schaden und Heilung. Im Kampf heilt Ihr und Brann alle 10 Sek. um 10 % des Schadens, den Ihr in dieser Zeit erlitten habt.\n\nStirbt ein Spielercharakter, gewährt die Aegis diesem bei der Wiederbelebung 2 % Schadensverringerung und 3 % erhöhte Heilung, reduziert jedoch seinen verursachten Schaden und die Heilung um 2 %. Dieser Effekt ist bis zu 3-mal stapelbar.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
