entries[1225925] = { ["name"] = "Gekonnte Schüsse", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nGallywix erhält alle 4 Sek. einen Stapel ' Gekonnte Schüsse '.\n\nBei Erreichen von 10 Stapeln oder bei einem Wechsel des Primärziels werden alle Schüsse abgegeben. Die Schüsse verursachen jeweils 3354035 körperlichen Schaden und 9 Sek. lang alle 1 Sek. 587001 zusätzlichen Feuerschaden. Dieser Effekt ist stapelbar und ihm kann nicht ausgewichen werden." }
entries[1225926] = { ["name"] = "Egoüberprüfung", ["text"] = "Sofort\nGallywix verpasst seinem Ziel eine 4er Tracht Prügel und verursacht mit jedem Treffer 13416139 körperlichen Schaden. Diese Schläge können nicht pariert oder ihnen ausgewichen werden.\n\nAußerdem werden 75% des nicht mitigierten Schadens als ' Geprüftes Ego ' verursacht." }
