entries[1226269] = { ["name"] = "Zorn des Verschlingers", ["text"] = "Unbegrenzte Reichweite\nSofort\nAdarus schleudert Kugeln aus gieriger Leere auf mehrere Positionen, die allen Spielercharakteren 5621532 kosmischen Schaden zufügen, wenn sie nicht abgefangen werden.\n\nAdarus fokussiert seinen Blick auf Spielercharaktere, die diese Kugeln abgefangen haben, greift sie kontinuierlich mit ' Verschlingen ' an und erhöht ihren erlittenen körperlichen Schaden um 100%.\n\nBei Entfernung wird ' Zorn des Verschlingers ' auf einen Spielercharakter in der Nähe übertragen und fügt allen Spielercharakteren 2108075 kosmischen Schaden zu." }
entries[1226270] = { ["name"] = "Stahlfallen", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrann wirft Stahlfallen, die beim ersten sich nähernden Gegner zuschnappen und ihm sofort moderaten körperlichen Schaden sowie zusätzlich regelmäßigen Blutungsschaden zufügen." }
