entries[1226277] = { ["name"] = "Entropisches Heulen", ["text"] = "Wirken in 4 sek.\nDer Zaubernde stößt ein markerschütterndes Heulen aus, das allen Spielercharakteren innerhalb von 60 Metern 5621532 Schattenschaden zufügt und 12 Sek. lang alle 1 Sek. zusätzlich 843230 Schattenschaden verursacht.\n\nAußerdem werden die Spielercharaktere durch dieses Heulen mit ' Entropischer Terror ' belegt." }
