entries[1226288] = { ["name"] = "Gekonnte Schüsse", ["text"] = "Unbegrenzte Reichweite\nSofort\nGallywix erhält alle 4 Sek. einen Stapel ' Gekonnte Schüsse '.\n\nBei Erreichen von 10 Stapeln oder bei einem Wechsel des Primärziels werden alle Schüsse abgegeben. Die Schüsse verursachen jeweils 3354035 körperlichen Schaden und 9 Sek. lang alle 1 Sek. 587001 zusätzlichen Feuerschaden. Dieser Effekt ist stapelbar und ihm kann nicht ausgewichen werden." }
