entries[1226511] = { ["name"] = "Frühlingsigel der Ernte", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Das Frühlingsschwein der Ernte hat früh morgens am meisten Energie. Es verbringt den Großteil des Tages damit, nach Futter zu schnüffeln oder nach anderen Ernteschweinen zu rufen.\"\nHandelsposten" }
