entries[1226531] = { ["name"] = "Sommerigel der Ernte", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Sommerigel der Ernte genießt es, einfach in der Sonne zu liegen oder in klarem Wasser zu schwimmen. Es zeigt hervorragende Leistungen bei der Nahrungssuche, doch es muss erst mal dazu überredet werden.\"\nHandelsposten" }
entries[1226532] = { ["name"] = "Winterigel der Ernte", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Winterigel der Ernte ist hauptsächlich nachtaktiv. Es ist etwas langsamer als andere Ernteigel, doch seine Ausdauer ist unübertroffen.\"\nHandelsposten" }
entries[1226533] = { ["name"] = "Herbstigel der Ernte", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Herbstigel der Ernte ist beim Erschnüffeln von Futter in kühleren Monaten nicht zu übertreffen. Sein ausgeprägter Geruchssinn macht es zu einem exzellenten Begleiter, wenn man in bewaldeten Gebieten auf Nahrungssuche geht, doch aromatischere Umgebungen könnten zum Problem werden.\"\nHandelsposten" }
